const dateParts = value => new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));
function dateLabel(value,withTime=true) { if(!value || Number.isNaN(new Date(value).getTime())) return '尚未设置'; return withTime ? dateParts(value) : new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric'}).format(new Date(value)); }
function timeLabel(value) { if(!value||Number.isNaN(new Date(value).getTime())) return '--:--'; return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)); }
function shortAgo(value) { if(!value) return ''; const minutes = Math.floor((Date.now()-new Date(value))/60000); return minutes<1 ? '刚刚' : minutes<60 ? `${minutes} 分钟前` : minutes<1440 ? `${Math.floor(minutes/60)} 小时前` : dateLabel(value,false); }
function dayKey(value) { if(value==null||Number.isNaN(new Date(value).getTime()))return '';return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)); }
function humanEvidence(value) { if(typeof value==='string') return value; return value?.text || value?.evidence || value?.content || value?.criterion || text(value); }
function badge(label,color='gray') { return `<span class="badge ${color}">${escape(label)}</span>`; }
