const btn = (action,label,symbol='',kind='',extra='') => `<button class="btn ${kind}" data-action="${action}" ${extra}>${symbol?icon(symbol):''}${escape(label)}</button>`;
function connectionStatus(name) { const connection=state.data?.connections?.[name] || {}; const good=connection.status==='connected'; const labels={not_configured:'待配置',disconnected:'未连接',error:'检测失败',need_auth:'需授权',needs_bot:'待启用机器人',permission_required:'缺少权限',resource_forbidden:'资源未授权',identity_unsupported:'身份不支持',need_login:'需登录',unauthorized:'需授权'};return `<span class="status-line"><i class="dot ${good?'green':connection.status==='error'?'red':connection.status!=='unknown'?'orange':''}"></i>${good?'已连接':labels[connection.status]||'待检测'}</span>`; }
function notify(message,error=false) { clearTimeout(toastTimer); document.getElementById('toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'info':'check')}<span>${escape(message)}</span></div>`; toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',error?9000:5000); }
function resultNotice(result,fallback) {const failures=Array.isArray(result?.failedTables)?result.failedTables.length:Number(result?.failedTables)||0;const partial=result?.status==='partial'||result?.status==='failed'||Number(result?.failed)>0||failures>0;notify(partial?`部分未完成：${result.message||`仍有 ${failures} 张表或 ${Number(result.failed)||0} 条记录需要处理，请查看执行记录。`}`:result?.message||fallback,partial);}
async function api(url,method='GET',body) {
  const response=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
  let result; try {result=await response.json();} catch {throw new Error(`服务返回异常（HTTP ${response.status}），请检查本地服务。`);}
  if(!response.ok || result.error) {const error=new Error(result.message || (typeof result.error==='string'?result.error:'操作未完成，请查看执行记录。'));error.payload=result;throw error;}
  return result;
}
async function loadWorkspace() { const result=await api('/api/workspace'); state.data=result.workspace || result; for(const key of ['requirements','candidates','applications','interviews','documents','activities','automations','conversations','messages','prompts','analyses','resumes','bossJobs','sourcingCandidates']) state.data[key] ||= []; state.data.settings ||= {}; state.data.schema ||= {tables:[]}; render(); }
async function run(button,fn) {
  const original=button?.innerHTML;
  if(button) {button.disabled=true;button.innerHTML='<span class="loading-spinner"></span>处理中…';}
  state.busy++;updateBusy();
  try {return await fn();} catch(error) {if(error.payload?.interview){closeOverlay();try{await loadWorkspace();setView('interviews');}catch{}}notify(error.message || '操作未完成',true); return null;}
  finally {state.busy--;updateBusy();if(button?.isConnected){button.disabled=false;button.innerHTML=original;}}
}
function updateBusy() { let line=document.getElementById('loading-line');if(state.busy&&!line){line=document.createElement('div');line.id='loading-line';line.className='loading-line';document.body.append(line);}if(!state.busy)line?.remove(); }
