function renderRequirements() { const rows=all('requirements').filter(r=>(!state.requirementStatus||r.status===state.requirementStatus)&&`${r.title} ${r.department} ${r.city}`.toLowerCase().includes(state.requirementQuery.toLowerCase())); return `${pageHeader('招聘需求','先对齐要招什么人，再让每一步工作沿着同一份标准推进。',btn('new-requirement','新建招聘需求','plus','primary'))}<div class="filters"><div class="search-input">${icon('search')}<input id="requirement-query" class="control" data-filter="requirementQuery" placeholder="搜索岗位、部门或城市" value="${escape(state.requirementQuery)}" aria-label="搜索招聘需求"></div><select class="control" data-filter="requirementStatus" aria-label="岗位状态"><option value="">全部状态</option>${Object.entries(reqStatuses).map(([key,label])=>`<option value="${key}" ${state.requirementStatus===key?'selected':''}>${label}</option>`).join('')}</select><span class="spacer"></span><span class="tiny muted">共 ${rows.length} 个岗位</span></div>${rows.length?`<div class="req-grid">${rows.map(r=>{const apps=applicationsFor(r.id);return `<article class="req-card"><div class="req-card-top">${badge(reqStatuses[r.status]||r.status,r.status==='open'?'green':r.status==='draft'?'orange':'gray')}${r.priority==='high'?badge('优先招聘','orange'):`<span class="tiny muted">标准 v${escape(r.version||1)}</span>`}</div><h3>${escape(r.title)}</h3><div class="req-card-desc"><span>${escape(r.department||'部门待完善')}</span><span>·</span><span>${escape(r.city||'城市待完善')}</span><span>·</span><span>${escape(r.headcount||1)} 人</span></div><div class="req-card-desc" style="margin-top:4px">${escape(r.salaryRange||'薪资待完善')}</div><div class="req-tags">${asArray(r.mustHaves).slice(0,3).map(t=>`<span>${escape(t)}</span>`).join('')||'<span>待完善岗位相关标准</span>'}</div><div class="req-numbers"><div><strong>${apps.length}</strong><small>入库候选人</small></div><div><strong>${apps.filter(a=>a.stage==='interview').length}</strong><small>面试中</small></div><div><strong>${apps.filter(a=>a.stage==='hired').length}</strong><small>已入职</small></div></div><div class="req-card-bottom"><span>负责人 · ${escape(r.owner||'待分配')}</span><div class="inline-actions"><button class="text-button" data-action="edit-requirement" data-id="${escape(r.id)}">编辑需求 ${icon('edit')}</button><button class="text-button" data-action="requirement-candidates" data-id="${escape(r.id)}">看人才 ${icon('arrow')}</button></div></div></article>`;}).join('')}</div>`:`<section class="panel">${noData('把招聘需求变成共同标准','创建岗位需求，明确工作职责、必备技能和面试标准。',btn('new-requirement','新建招聘需求','plus','primary'),'briefcase')}</section>`}<div class="notice" style="margin-top:22px">${icon('info')}候选人身份与应聘流程分开存储。同一位候选人可以关联多个岗位，各岗位独立记录阶段、证据与面试。</div>`;}
function filteredApplications() {return pooledApplications().filter(a=>{const c=candidateFor(a);const r=requirementFor(a);return (!state.requirementFilter||a.requirementId===state.requirementFilter)&&(!state.stageFilter||a.stage===state.stageFilter)&&[c?.name,c?.company,c?.position,c?.city,c?.degree,c?.school,c?.introduction,r?.title].filter(Boolean).join(' ').toLowerCase().includes(state.candidateQuery.toLowerCase());});}
function renderCandidates() {return state.poolView==='pipeline'?renderCandidatePipeline():candidatePool.renderPool();}
function conversationPreview(conversation) {const last=conversation.lastMessage;return typeof last==='string'?last:last?.text||last?.content||'暂未读取消息内容';}
function conversationBadge(conversation) {return badge(communicationNames[conversation.communicationStatus]||'待核实',communicationColors[conversation.communicationStatus]||'gray');}
function conversationHistoryInfo(conversation) {const rows=all('messages').filter(row=>row.conversationId===conversation.id&&row.type!=='preview');const speakers=new Set(rows.map(row=>row.sender).filter(sender=>['candidate','hr'].includes(sender)));return {hasHistory:rows.length>0,hasBoth:speakers.has('candidate')&&speakers.has('hr'),count:rows.length};}
function conversationRoundLabel(conversation) {const history=conversationHistoryInfo(conversation);return history.hasBoth&&conversation.roundCount!=null&&Number.isFinite(Number(conversation.roundCount))?`${Number(conversation.roundCount)} 次已记录往返`:'交流轮次待读取';}
function renderConversationProfile(conversation) {
  const profile=conversation.profile&&typeof conversation.profile==='object'?conversation.profile:null;
  const linked=conversation.candidateId?byId('candidates',conversation.candidateId):null;
  const supplied=value=>value!=null&&String(value).trim()!=='';
  const value=(key,candidateKey=key)=>{
    if(supplied(profile?.[key]))return {text:profile[key],source:'会话资料'};
    if(linked&&supplied(linked[candidateKey]))return {text:linked[candidateKey],source:'已关联主档'};
    return {text:profile?'来源未提供':'待读取',source:''};
  };
  const fact=(label,entry)=>`<div class="profile-fact"><label>${escape(label)}</label><strong>${escape(entry.text)}</strong>${entry.source==='已关联主档'?'<small>已关联主档补充</small>':''}</div>`;
  const rawOnly=key=>({text:supplied(profile?.[key])?profile[key]:profile?'来源未提供':'待读取',source:''});
  const availability=(flag)=>typeof flag==='boolean'?badge(flag?'来源标记可用':'来源标记不可用',flag?'green':'gray'):badge(profile?'来源未提供':'待读取','gray');
  const works=Array.isArray(profile?.workHistory)&&profile.workHistory.length?profile.workHistory:Array.isArray(linked?.workHistory)?linked.workHistory:[];
  const workSource=Array.isArray(profile?.workHistory)&&profile.workHistory.length?'本次会话资料':'已明确关联的候选人主档';
  const education=Array.isArray(profile?.education)&&profile.education.length?profile.education:linked&&(linked.school||linked.major)?[{school:linked.school,major:linked.major,degree:linked.degree}]:[];
  const eduSource=Array.isArray(profile?.education)&&profile.education.length?'本次会话资料':'已明确关联的候选人主档';
  const captured=profile?.sourceCapturedAt||(!profile?linked?.capturedAt:null);
  return `<section class="conversation-profile-card"><header class="conversation-profile-heading"><div><h3>${icon('users')}沟通人资料 ${profile?badge('已读取','green'):linked?badge('主档补充','blue'):badge('待读取','gray')}</h3><p>${profile?'按本次读取的职业资料展示，未提供字段保留缺口。':linked?'以下可用信息来自明确关联的候选人主档，尚未读取本次会话资料。':'读取沟通对象的职业背景与求职期望，保留来源与信息缺口。'}</p></div>${btn('read-conversation-profile','读取沟通人资料','refresh','small',`data-id="${escape(conversation.id)}"`)}</header><div class="profile-compact-facts">${fact('活跃状态',value('activeDesc'))}${fact('工作年限',value('workYear'))}${fact('学历',value('degree'))}${fact('沟通岗位',{text:conversation.communicatedPosition||profile?.communicatedPosition||'来源未提供',source:''})}</div><details class="profile-details"><summary><span>职业经历与求职期望</span><small>展开查看</small>${icon('down')}</summary><div class="profile-details-body"><div class="profile-full-facts">${fact('城市信息',value('city'))}${fact('职业 / 岗位',value('position'))}${fact('薪资信息',value('salary'))}${fact('期望城市',rawOnly('expectedCity'))}${fact('期望岗位',value('expectedPosition','position'))}${fact('期望薪资',value('expectedSalary','salary'))}</div>${supplied(profile?.introduction)||linked?.introduction?`<div class="profile-career-section"><h4>职业介绍 ${!supplied(profile?.introduction)&&linked?.introduction?'<small>已关联主档补充</small>':''}</h4><p>${escape(profile?.introduction||linked?.introduction)}</p></div>`:''}<div class="profile-career-grid"><div class="profile-career-section"><h4>近期工作经历${works.length?`<small>${escape(workSource)}</small>`:''}</h4>${works.length?works.map(work=>`<div class="profile-career-item"><strong>${escape(work.company||'公司名称来源未提供')}</strong><p>${escape(work.position||'职位来源未提供')}${work.dateRange?` · ${escape(work.dateRange)}`:''}</p></div>`).join(''):`<p class="profile-missing">${profile?'来源未提供工作经历':'待读取工作经历'}</p>`}</div><div class="profile-career-section"><h4>近期教育经历${education.length?`<small>${escape(eduSource)}</small>`:''}</h4>${education.length?education.map(edu=>`<div class="profile-career-item"><strong>${escape(edu.school||'院校来源未提供')}</strong><p>${escape([edu.major,edu.degree,edu.dateRange].filter(Boolean).join(' · ')||'专业及时间来源未提供')}</p></div>`).join(''):`<p class="profile-missing">${profile?'来源未提供教育经历':'待读取教育经历'}</p>`}</div></div><div class="profile-resume-status"><div><span>${icon('file')}附件简历</span>${availability(profile?.attachmentAvailable)}</div></div><p class="profile-source-note">${icon('info')}${captured?`来源采集时间：${dateLabel(captured)}。`:'来源采集时间待确认。'}以上为职业资料卡摘要。附件状态仅表示来源可用性，简历原件请在候选人档案中下载。</p></div></details></section>`;
}
function filteredConversations() {return [...all('conversations')].sort(advanced.priorityCompare).filter(conversation=>{
  const matchesStatus=!state.communicationFilter||(state.communicationFilter==='multi'?conversationHistoryInfo(conversation).hasBoth&&Number(conversation.roundCount)>=2:state.communicationFilter==='unread'?Number(conversation.unreadCount)>0:conversation.communicationStatus===state.communicationFilter);
  const haystack=[conversation.peerName,conversation.peerPosition,conversation.peerCompany,conversation.communicatedPosition,conversation.communicatedJobExternalId,conversationPreview(conversation),conversation.summary?.overview,byId('requirements',conversation.requirementId)?.title].filter(Boolean).join(' ').toLowerCase();
  return (!state.initiatorFilter||(conversation.initiator||'unknown')===state.initiatorFilter)&&matchesStatus&&advanced.conversationMatchesJob(conversation)&&advanced.matchesPriority(conversation)&&haystack.includes(state.conversationQuery.toLowerCase());
});}
function renderConversations() { return candidateInbox.renderInbox(); }

function renderConversationDetail(conversation) {
  const summary={...(conversation.summary||{}),replyDraft:conversation.replyPriority?.replyDraft&&!conversation.replyPriority.stale?conversation.replyPriority.replyDraft:''};const historyInfo=conversationHistoryInfo(conversation);if(!historyInfo.hasBoth)summary.overview=historyInfo.hasHistory?'已读取当前消息片段，尚不足以确认双方交流轮次。请结合原文和历史范围核实。':'目前仅有会话列表与最后消息预览，尚未读取双方历史；发起方与完整交流轮次仍需确认。';const requirement=byId('requirements',conversation.requirementId);const candidate=byId('candidates',conversation.candidateId);const application=all('applications').find(row=>row.candidateId===conversation.candidateId&&(!conversation.requirementId||row.requirementId===conversation.requirementId));
  const messages=all('messages').filter(message=>message.conversationId===conversation.id).sort((a,b)=>(new Date(a.sentAt).getTime()||0)-(new Date(b.sentAt).getTime()||0));
  return `<header class="conversation-detail-header"><div class="conversation-detail-person">${avatar({name:conversation.peerName})}<div><h2>${escape(conversation.peerName||'未命名候选人')} ${conversationBadge(conversation)}</h2><p>${escape([conversation.peerCompany].filter(Boolean).join(' · ')||'公司信息待补充')}</p></div></div><div class="inline-actions">${application?btn('candidate','候选人档案','users','small',`data-id="${escape(application.id)}"`):''}${btn('refresh-conversation','读取会话历史','refresh','small',`data-id="${escape(conversation.id)}"`)}</div></header><div class="conversation-provenance"><span class="initiator-tag ${conversation.initiator==='candidate'?'candidate':conversation.initiator==='hr'?'hr':''}">${escape(initiatorNames[conversation.initiator]||initiatorNames.unknown)}</span><span>${Number(conversation.messageCount)||messages.length} 条已采集消息</span><span>${escape(conversationRoundLabel(conversation))}</span><span>${conversation.historyComplete?'本次历史范围标记完整':'历史范围尚未确认完整'}</span></div><div class="conversation-detail-scroll">${renderConversationProfile(conversation)}<section class="communication-message-section"><div class="communication-section-title"><h3>${icon('chat')}会话记录</h3><span>${messages.length} 条本地已采集记录</span></div>${messages.length?`<div class="message-timeline">${renderMessageTimeline(messages,conversation)}</div>`:`<div class="message-timeline-empty"><div class="empty-symbol">${icon('chat')}</div><strong>先读取这段对话</strong><p>当前已同步会话列表，还没有读取这段历史。<br>读取后可核对双方原话与沟通进度。</p>${btn('refresh-conversation','读取会话历史','refresh','soft small',`data-id="${escape(conversation.id)}"`)}</div>`}<div class="history-coverage">${icon('info')}消息数量、往返次数和摘要仅针对本次已采集范围；未获取到最初消息时，不据最后发言推断发起方。</div></section><section class="communication-reply"><div class="communication-section-title"><h3>${icon('edit')}回复建议草稿</h3><span>审核后自行发送</span></div>${summary.replyDraft?`<div class="reply-draft">${escape(summary.replyDraft)}</div><div class="inline-actions" style="margin-top:12px">${btn('copy-reply-draft','复制回复草稿','copy','soft small',`data-id="${escape(conversation.id)}"`)}<span class="tiny muted">复制不会发送消息。</span></div>`:'<p class="communication-empty-copy">当前尚无有效的模板分析草稿。请在消息人选中按回复优先级模板分析，审核后自行回复。</p>'}</section><section class="communication-followup"><div class="communication-section-title"><h3>${icon('flow')}岗位关联与跟进</h3><span>保存到工作台，不修改 BOSS 状态</span></div><form id="conversation-followup-form" data-id="${escape(conversation.id)}"><div class="form-grid"><div class="field"><label for="conversation-requirement">关联招聘需求</label><select id="conversation-requirement" name="requirementId" class="control"><option value="">尚未关联岗位</option>${all('requirements').map(row=>`<option value="${escape(row.id)}" ${row.id===conversation.requirementId?'selected':''}>${escape(row.title)}</option>`).join('')}</select></div><div class="field"><label for="conversation-candidate">关联候选人主档</label><select id="conversation-candidate" name="candidateId" class="control"><option value="">尚未关联候选人</option>${all('candidates').map(row=>`<option value="${escape(row.id)}" ${row.id===conversation.candidateId?'selected':''}>${escape(row.name)} · ${escape(row.company||row.position||'')}</option>`).join('')}</select></div><div class="field"><label for="conversation-status">当前沟通进度</label><select id="conversation-status" name="communicationStatus" class="control">${Object.entries(communicationNames).map(([key,label])=>`<option value="${key}" ${(conversation.communicationStatus||'new')===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="conversation-followup">下次跟进（北京时间）</label><input id="conversation-followup" name="followUpAt" class="control" type="datetime-local" value="${escape(dateTimeInputValue(conversation.followUpAt))}"></div><div class="field full"><label for="conversation-notes">内部备注</label><textarea id="conversation-notes" name="notes" rows="3" class="control" placeholder="记录岗位匹配的事实、对方问题和下一步计划。">${escape(conversation.notes||'')}</textarea></div></div><div class="inline-actions" style="margin-top:15px"><button type="submit" class="btn primary">${icon('check')}保存跟进</button>${application?btn('schedule','安排面试','calendar','',`data-id="${escape(application.id)}"`):''}</div></form></section></div><footer class="conversation-detail-footer">${icon('shield')}本工作台不代发 BOSS 消息；沟通建议以岗位相关信息为依据，由你确认。</footer>`;
}
function dateTimeInputValue(value) {if(!value||Number.isNaN(new Date(value).getTime()))return '';const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));return parts.replace(' ','T');}
function renderMessageTimeline(messages,conversation) {let lastDay='';return messages.map(message=>{const day=dayKey(message.sentAt);const divider=day&&day!==lastDay?`<div class="message-date-divider"><span>${dateLabel(message.sentAt,false)}</span></div>`:'';lastDay=day;const sender=['candidate','hr','system'].includes(message.sender)?message.sender:'unknown';return `${divider}<div class="message-row ${sender}">${sender==='system'?`<div class="system-message">${escape(message.text||'系统记录')}</div>`:`<div class="message-author-avatar">${sender==='hr'?'HR':escape((conversation.peerName||'候').slice(0,1))}</div><div class="message-content"><div class="message-author">${escape(message.senderName||(sender==='hr'?'我方':sender==='candidate'?conversation.peerName||'候选人':'来源未确认'))}${message.type==='preview'?badge('最后消息预览','gray'):''}<time>${timeLabel(message.sentAt)}</time></div><div class="message-bubble">${escape(message.text||`[${message.type||'非文本消息'}]`)}</div></div>`}</div>`;}).join('');}
function renderCandidatePipeline() {const rows=filteredApplications();return `${pageHeader('候选人池 · 招聘流程','仅展示已入池人选的岗位流程；同一人可有多个岗位。',btn('pool-view','返回人选池','users','primary','data-layout="pool"'))}<div class="filters"><div class="search-input">${icon('search')}<input id="candidate-query" class="control" data-filter="candidateQuery" placeholder="搜索姓名、经历、学校或关键词" value="${escape(state.candidateQuery)}" aria-label="搜索候选人"></div><select class="control" data-filter="requirementFilter" aria-label="关联岗位"><option value="">全部岗位</option>${all('requirements').map(r=>`<option value="${escape(r.id)}" ${state.requirementFilter===r.id?'selected':''}>${escape(r.title)}</option>`).join('')}</select><select class="control" data-filter="stageFilter" aria-label="招聘阶段"><option value="">全部阶段</option>${Object.entries(stageNames).map(([key,label])=>`<option value="${key}" ${state.stageFilter===key?'selected':''}>${label}</option>`).join('')}</select><span class="spacer"></span><div class="segmented"><button data-action="candidate-layout" data-layout="table" class="${state.candidateLayout==='table'?'active':''}" title="列表视图">${icon('list')}列表</button><button data-action="candidate-layout" data-layout="board" class="${state.candidateLayout==='board'?'active':''}" title="看板视图">${icon('board')}看板</button></div></div><div class="toolbar-caption"><span>共 ${rows.length} 条应聘流程 · ${new Set(rows.map(r=>r.candidateId)).size} 位候选人</span><span>姓名保持平台掩码 · 不以年龄、性别作筛选或打分</span></div>${state.candidateLayout==='board'?`<div class="kanban">${Object.entries(stageNames).filter(([key])=>!state.stageFilter||key===state.stageFilter).map(([key,label])=>{const items=rows.filter(a=>a.stage===key);return `<section class="kanban-column"><div class="kanban-column-header">${label}<span>${items.length}</span></div>${items.map((a,index)=>{const c=candidateFor(a);return `<button class="kanban-card" data-action="candidate" data-id="${escape(a.id)}">${person(c,index)}<div class="tiny">${escape(c?.position||requirementFor(a)?.title||'职位待补充')}</div><div class="person-meta">${escape(c?.company||c?.school||'资料待补充')}</div><div style="display:flex;justify-content:space-between;margin-top:12px"><span class="source-pill">BOSS 直聘</span><span class="tiny muted">${escape(c?.salary||'薪资待确认')}</span></div></button>`;}).join('')||'<div class="kanban-empty">暂无候选人<br>在档案中人工调整阶段</div>'}</section>`;}).join('')}</div>`:`<section class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>候选人 / 背景</th><th>关联岗位 / 最近经历</th><th>期望薪资</th><th>当前阶段</th><th>来源</th><th>流程建立时间</th><th></th></tr></thead><tbody>${rows.map((a,index)=>{const c=candidateFor(a);return `<tr class="click-row" data-action="candidate" data-id="${escape(a.id)}"><td>${person(c,index)}</td><td>${escape(requirementFor(a)?.title||'未关联岗位')}<span class="cell-sub">${escape(c?.company||c?.position||'经历待完善')}</span></td><td class="no-wrap">${escape(c?.salary||'未提供')}</td><td>${stageBadge(a.stage)}</td><td><span class="source-pill">${escape(c?.sourceLabel?.includes('BOSS')?'BOSS 直聘':c?.sourceLabel||'BOSS 直聘')}</span></td><td class="tiny muted no-wrap">${dateLabel(a.createdAt||c?.capturedAt,false)}</td><td>${icon('chevron')}</td></tr>`;}).join('')}</tbody></table></div><div class="table-footer"><span>按平台候选人标识去重，候选人与岗位分别关联。</span><a href="/api/export/workspace" class="text-button">${icon('download')}导出工作空间</a></div>`:noData('没有找到匹配的人才','尝试其他关键词或筛选条件，也可以从已登录的 BOSS 搜索页同步。',btn('clear-candidate-filters','清空筛选','refresh','soft'),'users')}</section>`}`;}
function weekDays() {const now=new Date(`${dayKey(new Date())}T12:00:00+08:00`);const weekday=now.getUTCDay()||7;now.setUTCDate(now.getUTCDate()-weekday+1+state.weekOffset*7);return Array.from({length:7},(_,index)=>{const d=new Date(now);d.setUTCDate(d.getUTCDate()+index);return d;});}
function renderInterviews() {const days=weekDays();const sorted=[...all('interviews')].sort((a,b)=>new Date(a.startAt)-new Date(b.startAt));return `${pageHeader('面试日历','先准备有针对性的资料，再安排一次有价值的对话。',btn('schedule-picker','安排面试','plus','primary'))}<div class="notice blue">${icon('calendar')}本地安排会保存到当前工作空间。勾选同步飞书后，系统才会尝试创建真实日历日程，并显示返回结果。</div><section class="panel"><div class="calendar-toolbar"><div class="inline-actions"><button class="icon-button" data-action="calendar-week" data-offset="-1" aria-label="上一周" style="transform:rotate(180deg)">${icon('chevron')}</button><h3>${dateLabel(days[0],false)} — ${dateLabel(days[6],false)}</h3><button class="icon-button" data-action="calendar-week" data-offset="1" aria-label="下一周">${icon('chevron')}</button><button class="text-button" data-action="calendar-today">本周</button></div><div class="segmented"><button data-action="calendar-layout" data-layout="week" class="${state.calendarLayout==='week'?'active':''}">周视图</button><button data-action="calendar-layout" data-layout="list" class="${state.calendarLayout==='list'?'active':''}">全部日程</button></div></div>${state.calendarLayout==='week'?`<div class="table-wrap"><div class="week-grid">${days.map((day,index)=>{const items=sorted.filter(i=>dayKey(i.startAt)===dayKey(day));return `<div class="week-day"><div class="day-header ${dayKey(day)===dayKey(new Date())?'today':''}">${['周一','周二','周三','周四','周五','周六','周日'][index]}<div class="day-number">${new Date(day).getUTCDate()}</div></div>${items.map(i=>`<button class="interview-event" data-action="interview-detail" data-id="${escape(i.id)}"><time>${timeLabel(i.startAt)} – ${timeLabel(i.endAt)}</time><strong>${escape(i.title)}</strong><p>${escape(i.interviewer||'面试官待定')}<br>${escape(interviewCalendarState(i).label)}</p></button>`).join('')}</div>`;}).join('')}</div></div>`:sorted.length?sorted.map(renderInterviewRow).join(''):noData('还没有面试日程','从候选人档案发起面试，关联岗位标准、面试材料与面试官。',btn('schedule-picker','安排第一场面试','plus','soft'),'calendar')}</section>${!sorted.length?'<p class="input-note">安排面试前，建议先复核岗位相关经历并生成面试资料包。</p>':''}`;}
function renderInterviewRow(i) {const d=new Date(i.startAt);return `<div class="interview-row"><div class="interview-date"><small>${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'short'}).format(d)}</small><strong>${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',day:'numeric'}).format(d).replace('日','')}</strong></div><div class="interview-description"><h3>${escape(i.title)}</h3><p>${timeLabel(i.startAt)} – ${timeLabel(i.endAt)} · ${escape(i.interviewer||'面试官待定')} · ${escape(i.location||'地点待确认')}</p></div>${badge(interviewCalendarState(i).label,interviewCalendarState(i).color)}<div class="inline-actions">${btn('interview-detail','查看详情','arrow','small',`data-id="${escape(i.id)}"`)}</div></div>`;}
function renderDocuments() {const rows=latestDocumentsByCandidate(all('documents'),all('applications'));return `${pageHeader('面试资料中心','每位候选人展示最新一份面试资料，包含岗位标准、经历摘要和面试问题。',btn('navigate','前往候选人','users','soft','data-view="candidates"'))}<div class="notice">${icon('spark')}先收集岗位标准与候选人资料，再按会前准备模板生成面试问题。已收集资料和 AI 草稿分别标注，使用前请人工核对。</div>${rows.length?`<div class="doc-grid">${rows.map(d=>`<article class="doc-card"><div class="doc-card-top"><div class="doc-icon">${icon('file')}</div>${badge(documentGenerationStatus(d).label,documentGenerationStatus(d).tone)}</div><h3>${escape(d.title)}</h3><p>${escape(byId('candidates',d.candidateId||byId('applications',d.applicationId)?.candidateId)?.name||'候选人')} · ${escape(byId('requirements',d.requirementId)?.title||'关联岗位')}<br>${documentGenerationStatus(d).pending?'待生成问题':`${asArray(d.content?.questions).length} 个验证问题`} · ${asArray(d.content?.criteria).length} 项标准</p><div class="doc-card-footer"><span>${dateLabel(d.createdAt)}</span><button class="text-button" data-action="document" data-id="${escape(d.id)}">打开资料 ${icon('arrow')}</button></div></article>`).join('')}</div>`:`<section class="panel">${noData('为下一场面试做好准备','在候选人档案中生成资料包，自动整理经历摘要、岗位证据和待验证问题。',btn('navigate','选择候选人','users','primary','data-view="candidates"'),'file')}</section>`}`;}
function renderAutomations() {return `${pageHeader('自动化工作流','把重复工作交给脚本，把判断与确认留给人。',btn('navigate','检查连接','link','','data-view="settings"'))}<div class="notice">${icon('flow')}第一版提供手动触发与真实执行记录。未配置周期任务时不会后台自动运行，也不会主动联系或拒绝候选人。</div><div class="automation-grid">${all('automations').map((a,index)=>`<article class="automation-card"><div class="automation-card-header"><div class="round-icon">${icon(['refresh','file','calendar','database'][index%4])}</div><h3>${escape(a.name)}</h3>${badge(a.status==='running'?'运行中':a.status==='disabled'?'待配置':'手动触发',a.status==='running'?'green':'gray')}</div><p>${escape(a.description||'通过工作台手动执行，并记录每一步结果。')}</p><div class="automation-footer"><span>${a.lastRun?`上次运行 ${dateLabel(a.lastRun)}`:'尚未运行'}</span>${btn('automation-run','运行一次','play','small',`data-id="${escape(a.id)}" ${a.status==='running'?'disabled':''}`)}</div></article>`).join('')||noData('工作流尚未配置','需求、候选人和面试相关流程会在这里统一管理。','','flow')}</div><section class="panel" style="margin-top:22px"><div class="panel-header"><h2 class="panel-title">执行记录</h2><span class="tiny muted">操作结果按实际返回记录</span></div><div class="activity-list">${renderActivityItems(25)}</div></section>`;}
function renderFeishuAppConnection(){
  const settings=state.data.settings||{},connection=settings.feishuConnection,status=state.data.connections?.feishu;
  if(!connection)return '';
  return '<section class="panel" style="margin-bottom:20px"><div class="panel-header"><div><h2 class="panel-title">'+escape(settings.feishuAppName||'HR 专用飞书应用')+'</h2><p class="panel-subtitle">以应用身份运行，凭据由本机安全存储管理。</p></div>'+connectionStatus('feishu')+'</div><div class="panel-body"><p class="small muted">App ID：'+escape(connection.appId)+' · '+(connection.identity==='bot'?'应用身份':'用户身份')+'</p><p class="input-note">'+escape(status?.message||'等待检测应用连接。')+'</p>'+btn('check-feishu-app','检测 HR 应用','refresh','soft')+'<details style="margin-top:16px"><summary>更新本机应用凭据</summary><form id="feishu-credentials-form"><div class="field"><label for="feishu-app-secret">此应用的 App Secret</label><input id="feishu-app-secret" type="password" name="appSecret" class="control" autocomplete="new-password" required><small>仅用于上方 App ID，由工作台后台通过标准输入存入本机安全存储，不回传或导出。</small></div><button class="btn soft small" type="submit">保存并验证</button></form></details><p class="input-note">只检测飞书应用，不连接 BOSS。认证通过后，日历、会议和多维表仍需各自权限与资源授权。</p></div></section>';
}
function interviewAutomationSettingsPayload(values) {
  const result={enabled:values.enabled===true||values.enabled==='true',defaultReminderMinutes:Number(values.defaultReminderMinutes),reminderRecipientOpenId:String(values.reminderRecipientOpenId||'').trim(),meetingOwnerOpenId:String(values.meetingOwnerOpenId||'').trim(),pollSeconds:Number(values.pollSeconds),...automationRecipientSettingsPayload(values)};
  if(String(values.defaultReminderMinutes??'').trim()===''||!Number.isInteger(result.defaultReminderMinutes)||result.defaultReminderMinutes<0||result.defaultReminderMinutes>10080)throw new Error('默认提醒提前时间须为 0–10080 的整数分钟。');
  if(String(values.pollSeconds??'').trim()===''||!Number.isInteger(result.pollSeconds)||result.pollSeconds<5||result.pollSeconds>20)throw new Error('会议检测间隔须为 5–20 的整数秒。');
  for(const key of ['reminderRecipientOpenId','meetingOwnerOpenId'])if(result[key]&&!/^ou_[A-Za-z0-9_-]{1,200}$/.test(result[key]))throw new Error('请在高级设置中填写有效的当前 HR 应用飞书身份。');
  return result;
}
function renderInterviewAutomationRuntime() {
  const status=state.interviewAutomationStatus;if(!status)return '<div class="interview-automation-runtime-empty">尚未读取当前运行状态，可点击“刷新监测状态”。</div>';
  const queue=status.queue||{},enabled=status.enabled===true||status.settings?.enabled===true,label=!enabled?'监测已关闭':status.started===false?'监测器未运行':status.running?'正在执行':'等待面试任务';
  return `<div class="interview-automation-runtime-heading">${badge(label,!enabled?'gray':status.started===false?'orange':'green')}<span>${state.interviewAutomationStatusCheckedAt?`更新于 ${dateLabel(state.interviewAutomationStatusCheckedAt)}`:''}</span></div><div class="interview-automation-counts">${[['remindersPending','待提醒'],['meetingsWaiting','待入会'],['unknown','待核验'],['blocked','待处理']].map(([key,name])=>`<div><strong>${escape(Number(queue[key])||0)}</strong><span>${name}</span></div>`).join('')}</div><p class="input-note">${enabled?'任务仅在招聘工作台本地服务运行时执行。':'关闭监测不会删除已保存的面试与发送回执。'}单场执行结果可在面试详情核对。</p>`;
}
async function refreshInterviewAutomationStatus() {
  const result=await api('/api/interview-automation/status');state.interviewAutomationStatus=result;state.interviewAutomationStatusCheckedAt=new Date().toISOString();
  const target=document.getElementById('interview-automation-runtime');if(target)target.innerHTML=renderInterviewAutomationRuntime();return result;
}
async function saveInterviewAutomationSettings(values) {
  const payload=interviewAutomationSettingsPayload(values),result=await api('/api/interview-automation/settings','PATCH',payload);
  state.interviewAutomationStatus=result;state.interviewAutomationStatusCheckedAt=new Date().toISOString();await loadWorkspace();
  try{await refreshInterviewAutomationStatus();notify('面试自动化设置已保存。');}catch(error){notify(`设置已保存，运行状态读取未完成：${error.message}`,true);}
  return result;
}
function renderInterviewAutomationSettings() {
  const config=state.data.settings.interviewAutomation||{},minutes=config.defaultReminderMinutes??30,pollSeconds=config.pollSeconds??20;
  return `<section class="panel interview-automation-settings" id="interview-automation-settings"><div class="panel-header"><div><h2 class="panel-title">面试提醒与自动入会</h2><p class="panel-subtitle">设置默认面试官、消息环节、提醒时间与会议监测。</p></div>${badge(config.enabled?'已启用':'未启用',config.enabled?'green':'gray')}</div><form id="interview-automation-settings-form"><div class="panel-body"><label class="checkbox-line interview-automation-toggle"><input type="checkbox" name="enabled" value="true" ${config.enabled?'checked':''}><span>启用面试自动监测<br><small>只处理各场面试中已勾选的提醒与自动入会任务。</small></span></label>${renderDefaultInterviewNotificationSettings(state.data.settings,{escape})}<div class="form-grid"><div class="field"><label for="automation-default-reminder">默认提前提醒（分钟）*</label><input id="automation-default-reminder" name="defaultReminderMinutes" class="control" type="number" min="0" max="10080" step="1" required value="${escape(minutes)}"><small>默认 30 分钟；每场面试都可以单独调整，0 表示开始时提醒。</small></div><div class="field"><label for="automation-poll-seconds">会议检测间隔（秒）*</label><input id="automation-poll-seconds" name="pollSeconds" class="control" type="number" min="5" max="20" step="1" required value="${escape(pollSeconds)}"><small>默认 20 秒，可设为 5–20 秒。</small></div></div><details class="interview-automation-advanced"><summary>高级设置 · 飞书身份</summary><p>仅填写当前云咩咩应用确认的身份。日常接收人请在上方常用面试官中维护。</p><div class="form-grid"><div class="field"><label for="automation-reminder-recipient">兼容旧面试的提醒接收身份（可选）</label><input id="automation-reminder-recipient" name="reminderRecipientOpenId" class="control" value="${escape(config.reminderRecipientOpenId||'')}" placeholder="ou_…" pattern="ou_[A-Za-z0-9_-]{1,200}" autocomplete="off"><small>当前 HR 飞书应用的 open_id。</small></div><div class="field"><label for="automation-meeting-owner">默认会议发起人的飞书身份（可选）</label><input id="automation-meeting-owner" name="meetingOwnerOpenId" class="control" value="${escape(config.meetingOwnerOpenId||'')}" placeholder="ou_…" pattern="ou_[A-Za-z0-9_-]{1,200}" autocomplete="off"><small>新场次默认以首位已选面试官作为会议发起人，此处保留兼容默认值。</small></div></div></details><p class="interview-automation-explanation">自动入会仅在会前 30 分钟至面试结束期间监测；检测到会议开始后才申请入会，不会自动开会。请保持招聘工作台本地服务运行，实际结果以面试详情中的回执为准。</p><div class="inline-actions"><button type="submit" class="btn primary">${icon('check')}保存面试自动化设置</button>${btn('interview-automation-status','刷新监测状态','refresh','')}</div><div id="interview-automation-runtime" class="interview-automation-runtime" aria-live="polite">${renderInterviewAutomationRuntime()}</div></div></form></section>`;
}
function renderSettings() {const settings=state.data.settings;const tables=Array.isArray(state.data.schema)?state.data.schema:state.data.schema?.tables||[];return `${pageHeader('系统配置','统一配置模型 API、同步周期、BOSS 与飞书数据连接。',btn('check-connections','检测连接','refresh','primary'))}<div class="connection-grid">${[['boss','BOSS 直聘','BOSS','复用已登录 Chrome 会话，只访问当前账号已获授权的数据。'],['feishu','飞书服务','飞',settings.feishuConnection?'使用 HR 专用应用访问已授权的多维表、日历和会议。':'通过本机飞书 CLI 用户身份访问多维表与日历。'],['storage','业务数据底座','DB','需求、人才身份与应聘流程分表，面试和资料独立关联。']].map(([key,title,logo,description])=>`<section class="connection-card"><div class="connection-card-header"><div class="service-logo ${key}">${logo}</div>${key==='storage'?badge(state.data.connections?.storage?.mode==='feishu'?'已连接飞书':'本地存储',state.data.connections?.storage?.mode==='feishu'?'green':'orange'):connectionStatus(key)}</div><h3>${title}</h3><p>${escape(state.data.connections?.[key]?.message||description)}</p></section>`).join('')}</div>${renderFeishuAppConnection()}${renderInterviewAutomationSettings()}<div class="settings-grid"><div><section class="panel"><div class="panel-header"><div><h2 class="panel-title">连接配置</h2><p class="panel-subtitle">密钥与登录态留在本机，不在页面中显示。</p></div></div><form id="settings-form"><div class="panel-body"><div class="form-grid"><div class="field full"><label for="base-url">飞书多维表链接</label><input id="base-url" name="baseUrl" class="control" placeholder="粘贴现有飞书 Base 链接，或在下方新建" value="${escape(settings.baseUrl||'')}"><small>已有多维表先绑定；没有时可按右侧结构新建。</small></div><div class="field full"><label for="boss-work-mode">BOSS 工作模式</label><select id="boss-work-mode" name="bossOfflineMode" class="control"><option value="true" ${isBossOffline(state.data)?'selected':''}>离线整理已有数据</option><option value="false" ${!isBossOffline(state.data)?'selected':''}>允许连接已登录 BOSS</option></select><small>关闭离线模式本身不会启动采集。登录 BOSS 后，需另外启用周期同步或手动同步。</small></div><div class="field"><label for="cdp-port">Chrome CDP 端口</label><input id="cdp-port" name="cdpPort" type="number" min="1024" max="65535" class="control" value="${escape(settings.cdpPort||19222)}"><small>默认 19222，仅连接本机 Chrome。</small></div><div class="field"><label for="calendar-id">飞书日历 ID（可选）</label><input id="calendar-id" name="calendarId" class="control" value="${escape(settings.calendarId||'')}" placeholder="${settings.feishuConnection?.identity==='bot'?'填写此应用可管理的明确日历 ID':'留空使用个人主日历'}"></div></div><div class="inline-actions" style="margin-top:20px"><button class="btn primary" type="submit">${icon('check')}保存配置</button><a class="btn" href="/api/export/workspace">${icon('download')}导出本地数据</a></div></div></form></section><section class="panel"><div class="panel-header"><h2 class="panel-title">飞书多维表</h2>${badge(settings.baseToken?'已绑定':'待配置',settings.baseToken?'green':'gray')}</div><div class="panel-body"><p class="small muted" style="margin-bottom:15px">按右侧模型建立业务表。候选人使用平台标识去重，岗位申请独立保存阶段与标准快照，避免把同一个人的多次应聘混在一起。</p><div class="inline-actions">${btn('initialize-feishu','初始化招聘多维表','plus','soft')}${btn('sync-feishu','同步到飞书','refresh')}</div><p class="input-note">以上操作会实际写入飞书。系统会记录返回结果；未成功的同步不会显示为已完成。</p>${settings.baseUrl?`<a class="text-button" href="${safeLink(settings.baseUrl)}" target="_blank" rel="noopener noreferrer" style="margin-top:12px">打开已绑定多维表 ${icon('external')}</a>`:''}</div></section></div><section class="panel"><div class="panel-header"><div><h2 class="panel-title">业务表结构 <span class="count">${tables.length} 张关联表</span></h2><p class="panel-subtitle">各类资料独立存储，用稳定主键与关联字段串联。</p></div></div><div class="panel-body"><div class="schema-list">${tables.map((t,index)=>`<details class="schema-item"><summary><span class="schema-number">${String(index+1).padStart(2,'0')}</span><strong>${escape(t.name)}</strong><small>${asArray(t.fields).length} 个字段</small>${icon('chevron')}</summary><p class="schema-description">${escape(t.description||'')}</p><div class="schema-fields">${asArray(t.fields).map(f=>`<span>${escape(f.name||f.key)}<em>${escape(f.relation?'关联':f.type||'文本')}</em></span>`).join('')}</div></details>`).join('')}</div></div></section></div>`;}
function safeLink(value) {try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?escape(url.href):'#';}catch{return '#';}}
function closeOverlay() {advanced.stopLive?.();state.drawerId=null;overlays.innerHTML='';document.body.style.overflow='';}
function modal(title,subtitle,content,footer='',large=false,small=false) {advanced.stopLive?.();overlays.innerHTML=`<div class="modal-backdrop" data-action="overlay-close"><section class="modal ${large?'large':''} ${small?'small-modal':''}" role="dialog" aria-modal="true" aria-label="${escape(title)}"><div class="modal-header"><div><h2 class="modal-title">${escape(title)}</h2>${subtitle?`<p>${escape(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-content">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';advanced.enhanceRequirementForm?.();setTimeout(()=>overlays.querySelector('input:not([type=hidden]),select,textarea,button')?.focus(),50);}
function showRequirementForm(id) {const r=byId('requirements',id)||{};modal(id?'编辑招聘需求':'新建招聘需求','把工作职责与必备能力写清楚，后续资料和面试沿用同一份标准。',`<form id="requirement-form" data-id="${escape(id||'')}"><div class="form-grid"><div class="field"><label for="req-title">岗位名称 *</label><input id="req-title" name="title" class="control" required maxlength="100" value="${escape(r.title||'')}" placeholder="如：HRBP / 跨境电商运营"></div><div class="field"><label for="req-department">用人部门</label><input id="req-department" name="department" class="control" value="${escape(r.department||'')}" placeholder="如：组织与人才发展部"></div><div class="field"><label for="req-city">工作城市</label><input id="req-city" name="city" class="control" value="${escape(r.city||'')}" placeholder="如：杭州"></div><div class="field"><label for="req-headcount">招聘人数 *</label><input id="req-headcount" name="headcount" type="number" min="1" max="1000" class="control" value="${escape(r.headcount||1)}" required></div><div class="field"><label for="req-salary">薪资范围</label><input id="req-salary" name="salaryRange" class="control" value="${escape(r.salaryRange||'')}" placeholder="如：13–20K / 月"></div><div class="field"><label for="req-owner">需求负责人</label><input id="req-owner" name="owner" class="control" value="${escape(r.owner||'')}" placeholder="姓名或飞书邮箱"></div><div class="field"><label for="req-status">需求状态</label><select id="req-status" name="status" class="control">${Object.entries(reqStatuses).map(([k,v])=>`<option value="${k}" ${(r.status||'draft')===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="req-priority">优先级</label><select id="req-priority" name="priority" class="control">${[['normal','正常'],['high','优先'],['low','低优先级']].map(([k,v])=>`<option value="${k}" ${(r.priority||'normal')===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label for="req-jd">工作职责 / JD</label><textarea id="req-jd" name="jd" class="control" rows="4" placeholder="描述实际负责的业务、工作目标和团队环境。">${escape(r.jd||'')}</textarea></div><div class="field full"><label for="req-must">必备能力与验证标准（每行一项）</label><textarea id="req-must" name="mustHaves" class="control" rows="4" placeholder="例如：独立负责过业务团队的招聘与组织支持&#10;能够通过具体项目说明业务理解与协作能力">${escape(asArray(r.mustHaves).join('\n'))}</textarea><small>只填写与工作相关的职责、经验和能力要求，后续面试问题以此为依据。</small></div></div></form>`,`<span class="footnote">修改后保留岗位标准版本，历史面试资料不自动改写。</span>${btn('close','取消') }<button class="btn primary" type="submit" form="requirement-form">${icon('check')}保存需求</button>`);}
function openCandidate(id,tab='profile') {const application=byId('applications',id);if(!inCandidatePool(candidateFor(application))){notify('请先从搜索 / 推荐或消息来源中加入候选人池。');return;}advanced.stopLive?.();state.drawerId=id;state.drawerTab=tab;renderDrawer();}
function renderDrawer() {const a=byId('applications',state.drawerId);if(!a)return;const c=candidateFor(a)||{};const r=requirementFor(a)||{};const docs=all('documents').filter(d=>d.applicationId===a.id);const interviews=all('interviews').filter(i=>i.applicationId===a.id);const activities=all('activities').filter(i=>i.applicationId===a.id||i.candidateId===c.id);let body='';
  if(state.drawerTab==='profile')body=`<section class="drawer-section"><h3>${icon('briefcase')}应聘关系</h3><div class="drawer-facts"><div class="drawer-fact"><label>关联岗位</label><span>${escape(r.title||'未关联')}</span></div><div class="drawer-fact"><label>期望岗位</label><span>${escape(c.position||'未提供')}</span></div><div class="drawer-fact"><label>期望薪资</label><span>${escape(c.salary||'未提供')}</span></div><div class="drawer-fact"><label>资料来源</label><span>${escape(c.sourceLabel||'BOSS 直聘')}</span></div></div></section><section class="drawer-section"><h3>${icon('file')}经历摘要 · 平台原文</h3><p>${escape(c.introduction||'当前列表未提供经历摘要，请在面试前进一步核实。')}</p></section><section class="drawer-section"><h3>${icon('briefcase')}工作经历</h3>${asArray(c.workHistory).length?asArray(c.workHistory).map(w=>`<div class="history-item"><strong>${escape(w.company||w.name||'公司未提供')}</strong><small>${escape(w.position||'职位未提供')}${w.dateRange?` · ${escape(w.dateRange)}`:''}</small></div>`).join(''):`<p>${escape(c.company||'列表未提供工作经历，需补充资料。')}</p>`}</section><section class="drawer-section"><h3>${icon('file')}教育摘要</h3><div class="drawer-facts"><div class="drawer-fact"><label>院校</label><span>${escape(c.school||'未提供')}</span></div><div class="drawer-fact"><label>专业 / 学历</label><span>${escape([c.major,c.degree].filter(Boolean).join(' · ')||'未提供')}</span></div></div></section><div class="notice">${icon('info')}这里展示平台列表与已保存资料，不代表已获得完整简历。信息缺口会保留为待验证事项。</div>`;
  else if(state.drawerTab==='evidence')body=`<section class="drawer-section"><h3>${icon('shield')}岗位标准 v${escape(r.version||1)}</h3>${asArray(r.mustHaves).length?asArray(r.mustHaves).map(criterion=>`<div class="evidence-row"><h4>${escape(criterion)}</h4><p>请结合真实经历核对证据，未验证项将在面试包中列为提问。</p></div>`).join(''):'<p>岗位标准尚未完善。先在招聘需求中补充职责与必备能力。</p>'}</section><section class="drawer-section"><h3>${icon('file')}已记录的证据</h3>${asArray(a.evidence).length?asArray(a.evidence).map(e=>`<div class="evidence-row"><p>${escape(humanEvidence(e))}</p></div>`).join(''):'<p>当前尚未补充人工核实的证据。生成面试包可整理原文线索与待验证点。</p>'}</section><div class="notice">${icon('shield')}不对候选人作自动录用或淘汰判断。请基于与岗位相关的证据人工复核。</div>${btn('mark-reviewed','标记已人工复核','check','soft',`data-id="${escape(a.id)}"`)}`;
  else if(state.drawerTab==='materials')body=`<section class="drawer-section"><h3>${icon('file')}面试资料 <span class="badge gray">${docs.length}</span></h3>${docs.length?docs.map(d=>`<div class="evidence-row"><h4>${escape(d.title)}</h4><p>${dateLabel(d.createdAt)} · ${documentGenerationStatus(d).detail}</p><button class="text-button" style="margin-top:10px" data-action="document" data-id="${escape(d.id)}">查看资料与问题 ${icon('arrow')}</button></div>`).join(''):noData('还没有面试资料','根据岗位标准和当前经历生成资料、问题与验证清单。',btn('generate-pack','生成面试包','spark','soft',`data-id="${escape(a.id)}"`),'file')}</section><section class="drawer-section"><h3>${icon('calendar')}关联面试</h3>${interviews.length?interviews.map(i=>`<div class="evidence-row"><h4>${escape(i.title)}</h4><p>${dateLabel(i.startAt)} · ${escape(i.interviewer||'面试官待定')}</p><button class="text-button" style="margin-top:8px" data-action="interview-detail" data-id="${escape(i.id)}">查看安排 ${icon('arrow')}</button></div>`).join(''):'<p>尚未安排面试。</p>'}</section>`;
  else body=`<form id="application-notes-form" data-id="${escape(a.id)}"><section class="drawer-section"><h3>${icon('edit')}内部跟进记录</h3><textarea name="notes" class="control" style="width:100%;min-height:180px;line-height:2" placeholder="记录已核实事实、沟通结果和下一步行动。">${escape(a.notes||'')}</textarea><div class="inline-actions" style="margin-top:12px"><button class="btn soft" type="submit">${icon('check')}保存记录</button></div></section></form><section class="drawer-section"><h3>${icon('clock')}活动记录</h3>${activities.length?activities.map(i=>`<div class="history-item"><strong>${escape(i.title)}</strong><small>${escape(i.detail||'')} · ${dateLabel(i.createdAt)}</small></div>`).join(''):`<div class="history-item"><strong>候选人入库</strong><small>${dateLabel(a.createdAt||c.capturedAt)}</small></div>`}</section>`;
  overlays.innerHTML=`<div class="drawer-backdrop" data-action="overlay-close"><aside class="drawer" role="dialog" aria-modal="true" aria-label="候选人档案"><div class="drawer-header"><div class="drawer-person">${avatar(c)}<div><h2>${escape(c.name||'候选人')}</h2><p>${escape([c.workYear,c.degree,c.city].filter(Boolean).join(' · '))}</p></div><button class="icon-button" data-action="close" aria-label="关闭档案">${icon('close')}</button></div><div class="drawer-keyfacts">${stageBadge(a.stage)}${badge(a.reviewStatus==='reviewed'?'已人工复核':'待人工复核',a.reviewStatus==='reviewed'?'green':'orange')}<span class="badge gray">BOSS 直聘</span></div></div><nav class="drawer-tabs">${[['profile','档案概览'],['evidence','岗位证据'],['materials','面试资料'],['notes','跟进记录']].map(([key,label])=>`<button class="${state.drawerTab===key?'active':''}" data-action="drawer-tab" data-tab="${key}">${label}</button>`).join('')}</nav><div class="drawer-body">${body}<section class="drawer-section" style="border-top:1px solid var(--line);padding-top:19px"><h3>${icon('flow')}人工推进阶段</h3><form id="application-stage-form" data-id="${escape(a.id)}" class="inline-actions"><select name="stage" class="control" aria-label="更新候选人阶段">${Object.entries(stageNames).map(([key,label])=>`<option value="${key}" ${a.stage===key?'selected':''}>${label}</option>`).join('')}</select><button class="btn small soft" type="submit">保存阶段</button></form></section></div><div class="drawer-footer">${btn('generate-pack','生成面试资料','spark','soft',`data-id="${escape(a.id)}"`)}${btn('schedule','安排面试','calendar','primary',`data-id="${escape(a.id)}"`)}</div></aside></div>`;document.body.style.overflow='hidden';advanced.enhanceDrawer();
}
function showImportForm() {if(isBossOffline(state.data)){notify('当前仅整理已保存资料，暂不连接 BOSS。');return;}if(!all('requirements').length){showRequirementForm();notify('请先创建一个岗位，再同步候选人。');return;}modal('获取 BOSS 搜索 / 推荐人选','保存到来源列表并关联评估岗位，不会自动加入候选人池。',`<form id="boss-import-form"><div class="field"><label for="import-requirement">关联招聘需求 *</label><select id="import-requirement" name="requirementId" class="control" required>${all('requirements').map(r=>`<option value="${escape(r.id)}" ${state.requirementFilter===r.id?'selected':''}>${escape(r.title)} · ${escape(reqStatuses[r.status]||r.status)}</option>`).join('')}</select></div><div class="notice" style="margin:18px 0 0">${icon('info')}请保持 Chrome 的 BOSS 搜索页打开且已登录。同步复用页面请求客户端，按平台候选人标识去重。遇到验证或权限限制会停止并显示原因。</div><p class="input-note">首版同步当前页面范围，不会将服务端声明的总量标记为已全部采集。</p></form>`,`${btn('close','取消')}<button class="btn primary" type="submit" form="boss-import-form">${icon('refresh')}开始同步</button>`,false,true);}
function showSchedulePicker() {
  const options=eligibleInterviewApplications({applications:pooledApplications(),requirements:all('requirements')});
  if(!options.length){notify('先从来源列表加入候选人池并关联岗位，再安排面试。');setView('candidates');return;}
  modal('选择面试候选人','选择关联岗位的候选人，随后填写时间与面试官。',`<form id="schedule-picker-form"><div class="field"><label for="schedule-application">候选人与岗位 *</label><select id="schedule-application" class="control" name="applicationId" required><option value="">请选择候选人与本场面试岗位</option>${options.map(a=>`<option value="${escape(a.id)}">${escape(candidateFor(a)?.name||'候选人')} · ${escape(requirementFor(a)?.title||'岗位')} · ${escape(candidateFor(a)?.company||'')}</option>`).join('')}</select></div></form>`,`${btn('close','取消')}<button class="btn primary" form="schedule-picker-form" type="submit">下一步 ${icon('arrow')}</button>`,false,true);
}
function showScheduleForm(id) {
  const a=byId('applications',id);if(!a)return;const c=candidateFor(a);
  if(!inCandidatePool(c)){notify('先将该人选加入候选人池，再推进面试。');return;}
  const r=requirementFor(a);if(!r||a.stage==='archived'){notify('本场关联岗位已失效，请先选择有效招聘需求。',true);return;}
  const tomorrow=dayKey(Date.now()+86400000),reminderMinutes=defaultReminderMinutes(state.data?.settings);
  modal('安排面试','按本场岗位与现有候选人资料准备面试问题，并保存提醒和入会设置。',`<form id="schedule-form" data-id="${escape(a.id)}"><div class="requirement-summary"><h4>${escape(c?.name||'候选人')} · ${escape(r.title)}</h4><p>${escape([c?.workYear,c?.degree,c?.company].filter(Boolean).join(' · '))}</p><p class="input-note">面试问题将依据本场岗位标准与已取得资料自动准备，可在“会前准备”中核对。</p></div><div class="form-grid"><div class="field full"><label for="interview-title">日程标题 *</label><input id="interview-title" class="control" name="title" required value="${escape(`${c?.name||'候选人'} · ${r.title}面试`)}"></div><div class="field"><label for="interview-start">开始时间（北京时间）*</label><input id="interview-start" class="control" name="startAt" type="datetime-local" required value="${tomorrow}T10:00"></div><div class="field"><label for="interview-end">结束时间（北京时间）*</label><input id="interview-end" class="control" name="endAt" type="datetime-local" required value="${tomorrow}T11:00"></div><div class="field"><label for="interviewer">面试官备注（可选）</label><input id="interviewer" class="control" name="interviewer" placeholder="下方搜名字勾选即可；旧安排方式可填姓名"></div><div class="field"><label for="interview-round">面试轮次</label><select id="interview-round" class="control" name="round"><option value="初面">初面</option><option value="复面">复面</option><option value="终面">终面</option><option value="业务沟通">业务沟通</option></select></div><div class="field full"><label for="interview-location">会议地点或链接</label><input id="interview-location" class="control" name="location" placeholder="如：线上飞书会议 / 3 楼会议室"></div><fieldset class="interview-schedule-options field full"><legend>飞书日程与机器人</legend><label class="checkbox-line"><input type="checkbox" name="createCalendar" value="true" checked><span>自动创建飞书日历日程<br><small>使用已连接的 HR 飞书应用实际创建，详情保留日程 ID 和创建结果。</small></span></label><div class="field interview-reminder-minutes"><label for="interview-reminder-minutes">提前多少分钟提醒 *</label><input id="interview-reminder-minutes" class="control" name="reminderMinutes" type="number" min="0" max="10080" step="1" required value="${reminderMinutes}"><small>默认 ${reminderMinutes} 分钟，可按本场调整；0 表示开始时提醒。</small></div><label class="checkbox-line"><input type="checkbox" name="autoJoinEnabled" value="true" checked><span>会议开始后机器人自动入会<br><small>需有可识别的飞书会议和入会权限；可在详情核对实际入会状态。</small></span></label></fieldset>${renderScheduleNotificationOptions(state.data.settings,{escape})}</div></form>`,`<span class="footnote">按已沟通的时间安排；日程、提醒和入会分别显示执行回执。</span>${btn('close','取消')}<button class="btn primary" type="submit" form="schedule-form">${icon('calendar')}确认安排</button>`);
}
function showDocument(id) {const d=byId('documents',id);if(!d)return;const candidate=d.candidateId?byId('candidates',d.candidateId):byId('candidates',byId('applications',d.applicationId)?.candidateId);const content=d.content||{};const summary=typeof content==='string'?content:content.summary||'尚未生成摘要';modal(d.title||'面试资料包',`${dateLabel(d.updatedAt||d.createdAt)}`,`${!documentGenerationStatus(d).generated?`<div class="notice">${icon('info')}${documentGenerationStatus(d).pending?'岗位与候选资料已收集，尚未按当前模板生成面试问题。请到会前准备中生成并复核问题。':'这份历史资料草稿保留原来的内容与来源，使用前请按当前岗位标准复核。'}</div>`:''}${renderCandidateBrief(content,{escape})||`<section class="doc-section"><h3>${icon('users')}候选人与岗位摘要</h3><div class="doc-summary">${escape(text(summary))}</div></section>`}${renderPreparationScore(content.scoreSummary,{escape,badge})}${asArray(content.criteria).length?`<details class="doc-section document-criteria"><summary><span>${icon('shield')}岗位标准与经历证据 <small>${asArray(content.criteria).length} 项</small></span><span class="document-criteria-toggle">查看依据 ${icon('down')}</span></summary><div class="document-criteria-body">${asArray(content.criteria).map(item=>`<div class="evidence-row"><h4>${escape(item.criterion||item.title||humanEvidence(item))}</h4>${item.evidence?`<p>证据线索：${escape(text(item.evidence))}</p>`:''}${item.gap?`<p>待验证：${escape(text(item.gap))}</p>`:''}</div>`).join('')}</div></details>`:''}${asArray(content.questions).length?`<section class="doc-section"><h3>${icon('spark')}面试验证问题 <span class="badge gray">${asArray(content.questions).length}</span></h3>${asArray(content.questions).map((q,index)=>renderInterviewQuestion(q,index,{escape,badge})).join('')}</section>`:''}${asArray(content.agenda).length?`<section class="doc-section"><h3>${icon('clock')}建议面试议程</h3>${asArray(content.agenda).map((item,index)=>`<div class="agenda-item"><b>${escape(item.duration||item.time||String(index+1).padStart(2,'0'))}</b><span>${escape(typeof item==='string'?item:item.title||item.topic||item.content||text(item))}</span></div>`).join('')}</section>`:''}${content.notes?`<details class="doc-section preparation-notes"><summary>资料说明</summary><p>${escape(asArray(content.notes).map(text).join('\n'))}</p></details>`:''}`,`${candidate?btn('candidate-profile-edit','编辑候选人资料','edit','',`data-id="${escape(candidate.id)}"`):''}<a class="btn" href="/api/documents/${encodeURIComponent(d.id)}/download" target="_blank" rel="noopener">${icon('download')}导出资料</a>${btn('close','关闭')}`,true);}
function showInterviewDetailBasic(id) {const i=byId('interviews',id);if(!i)return;const doc=byId('documents',i.documentId)||all('documents').find(d=>d.applicationId===i.applicationId);modal(i.title||'面试详情',`${escape(i.round||'面试')} · ${i.calendarStatus==='synced'?'已同步飞书日历':'本地面试安排'}`,`<div class="drawer-facts"><div class="drawer-fact"><label>开始时间</label><span>${dateLabel(i.startAt)}</span></div><div class="drawer-fact"><label>结束时间</label><span>${dateLabel(i.endAt)}</span></div><div class="drawer-fact"><label>面试官</label><span>${escape(i.interviewer||'待完善')}</span></div><div class="drawer-fact"><label>面试轮次</label><span>${escape(i.round||'未设置')}</span></div><div class="drawer-fact" style="grid-column:1/-1"><label>地点 / 会议链接</label><span>${escape(i.location||'待确认')}</span></div></div><div class="notice" style="margin:23px 0 0">${icon('info')}${i.calendarStatus==='synced'?'飞书日程已创建，具体邀请与参会状态以飞书返回为准。':'当前安排保存在本地。可在信息确认后创建飞书日历日程。'}</div>${i.calendarError?`<p class="inline-warning">${escape(i.calendarError)}</p>`:''}`,`${doc?btn('document','打开面试资料','file','',`data-id="${escape(doc.id)}"`):btn('generate-pack','生成面试资料','spark','',`data-id="${escape(i.applicationId)}"`)}${i.calendarStatus==='synced'&&i.calendarUrl?`<a class="btn primary" href="${safeLink(i.calendarUrl)}" target="_blank" rel="noopener">打开飞书日程 ${icon('external')}</a>`:i.calendarStatus!=='synced'?btn('sync-interview','创建飞书日程','calendar','primary',`data-id="${escape(i.id)}"`):btn('close','关闭')}`);}
function confirmInitialize() {const tables=Array.isArray(state.data.schema)?state.data.schema:state.data.schema?.tables||[];modal('初始化飞书招聘多维表','这一步会向已登录的飞书账号写入新表结构。',`<div class="confirm-copy">将按当前模型创建或初始化招聘数据底座，包含 ${tables.length} 张关联业务表：</div><div class="pill-list" style="margin:17px 0">${tables.map(t=>`<span>${escape(t.name)}</span>`).join('')}</div><p class="input-note">系统将保留创建回执。若权限或网络受限，会显示实际失败原因；不会将本地数据冒充为已同步。</p>`,`${btn('close','暂不创建')}${btn('initialize-feishu-confirm','确认初始化','database','primary')}`,false,true);}
function confirmPull() {modal('从飞书读取业务记录','读取已绑定的业务表，并更新本地工作空间。',`<p class="confirm-copy">飞书中具有相同工作台 ID 的记录将更新本地对应记录。本地尚未同步到飞书的新增记录会保留。</p><div class="notice warning" style="margin:18px 0 0">${icon('info')}同 ID 的本地修改可能被飞书当前版本替换。若需要保留这些修改，请先导出备份或同步到飞书，再执行回读。</div><a class="text-button" href="/api/export/workspace" style="margin-top:14px">${icon('download')}先导出本地备份</a>`,`${btn('close','取消')}${btn('pull-feishu-confirm','确认从飞书读取','download','primary')}`,false,true);}
function showInterviewDetailLegacy(id) {
  showInterviewDetailBasic(id);
  const interview=byId('interviews',id);if(!interview)return;
  const review=interview.transcriptReview;
  overlays.querySelector('.modal')?.classList.add('large');
  overlays.querySelector('.modal-content')?.insertAdjacentHTML('beforeend',`<section class="doc-section transcript-section"><h3>${icon('edit')}会中记录与证据核对</h3><p class="transcript-description">粘贴人工访谈记录或逐字稿，保存原文并生成岗位问题核对清单。当前不连接实时字幕，不将核对清单作为自动评估结论。</p><form id="interview-notes-form" data-id="${escape(id)}"><div class="field"><label class="sr-only" for="interview-transcript">面试记录或逐字稿</label><textarea id="interview-transcript" class="control" name="transcript" rows="7" required placeholder="记录候选人原话、本人负责的行动、具体结果，以及尚待追问的内容。">${escape(review?.transcript||'')}</textarea></div><div class="inline-actions" style="margin-top:12px"><button class="btn soft" type="submit">${icon('check')}保存并生成核对清单</button>${review?badge('人工核对草稿','orange'):''}</div></form>${review?`<div class="transcript-review"><p class="input-note">${escape(review.note||'以下条目需要人工核对与确认。')}</p>${asArray(review.reminders).map(reminder=>`<div class="evidence-row"><h4>${escape(reminder.topic||'待核对事项')}</h4><p>原文片段：${escape(reminder.evidence||'待标注')}</p><p>核对提醒：${escape(reminder.question||'请补充事实证据')}</p></div>`).join('')}</div>`:''}</section>`);
}

function showInterviewDetail(id) {advanced.showInterviewWorkspace(id,'live');}

const advanced=createAdvancedFeatures({state,all,byId,api,run,notify,resultNotice,render,loadWorkspace,setView,icon,escape,text,badge,btn,pageHeader,dateLabel,modal,closeOverlay,showRequirementForm,openCandidate,showSchedulePicker});
const candidateFeatureContext={state,all,byId,api,run,notify,resultNotice,render,loadWorkspace,setView,icon,escape,text,badge,btn,pageHeader,dateLabel,modal,closeOverlay,showImportForm};
const candidateProfileEditor=createCandidateProfileEditor({...candidateFeatureContext,closeOverlay});
const sourcingCandidates=createSourcingCandidatesFeatures(candidateFeatureContext);
const candidatePool=createCandidatePoolFeatures({...candidateFeatureContext,openCandidate,showScheduleForm,openSourcingDetails:id=>sourcingCandidates.showDetails(id),openConversationDetails:id=>candidateInbox.showDetails(id)});
const candidateInbox=createCandidateInboxFeatures(candidateFeatureContext);

const recipientDirectory=createRecipientDirectoryController({api,escape,currentAppId:()=>state.data?.settings?.feishuConnection?.appId||''});
document.addEventListener('click',event=>{
  if(recipientDirectory.handleClick(event))return;
  const button=event.target.closest('[data-action]');if(!button)return;
  const {action,id,view}=button.dataset;
  if(candidateProfileEditor.handleAction(button,event))return;
  if(isBossOffline(state.data)&&(['priority-run-inbox','import-conversations','refresh-conversation','read-conversation-profile','check-connections'].includes(action)||action==='automation-run'&&/^boss-/.test(id||''))){notify('当前仅整理已保存资料，暂不连接 BOSS。');return;}
  if(sourcingCandidates.handleAction(button,event)||candidatePool.handleAction(button,event)||candidateInbox.handleAction(button,event))return;
  if(advanced.handleAction(button,event))return;
  if(action==='overlay-close'&&event.target!==button)return;
  if(action==='navigate'){closeOverlay();setView(view);}
  else if(action==='mobile-menu'){state.mobileOpen=!state.mobileOpen;render();}
  else if(action==='close'||action==='overlay-close')closeOverlay();
  else if(action==='new-requirement')showRequirementForm();
  else if(action==='edit-requirement')showRequirementForm(id);
  else if(action==='requirement-candidates'){state.requirementFilter=id;state.stageFilter='';setView('candidates');}
  else if(action==='candidate')openCandidate(id);
  else if(action==='select-conversation'){candidateInbox.showDetails(id);}
  else if(action==='open-conversation'){state.selectedConversationId=id;setView('conversations');candidateInbox.showDetails(id);}
  else if(action==='clear-conversation-filters'){state.conversationQuery='';state.initiatorFilter='';state.communicationFilter='';state.communicatedJobFilter='';state.priorityFilter='';render();}
  else if(action==='drawer-tab'){state.drawerTab=button.dataset.tab;renderDrawer();}
  else if(action==='filter-stage'){state.stageFilter=button.dataset.stage;state.poolView='pipeline';setView('candidates');}
  else if(action==='candidate-layout'){state.candidateLayout=button.dataset.layout;render();}
  else if(action==='clear-candidate-filters'){state.candidateQuery='';state.stageFilter='';state.requirementFilter='';render();}
  else if(action==='calendar-layout'){state.calendarLayout=button.dataset.layout;render();}
  else if(action==='calendar-week'){state.weekOffset+=Number(button.dataset.offset);render();}
  else if(action==='calendar-today'){state.weekOffset=0;render();}
  else if(action==='import-boss')setView('sourcing');
  else if(action==='schedule-picker')showSchedulePicker();
  else if(action==='schedule')showScheduleForm(id);
  else if(action==='document')showDocument(id);
  else if(action==='interview-detail')showInterviewDetail(id);
  else if(action==='initialize-feishu')confirmInitialize();
  else if(action==='pull-feishu')confirmPull();
  else if(action==='refresh')run(button,async()=>{await loadWorkspace();notify('工作台数据已刷新。');});
  else if(action==='import-conversations')run(button,async()=>{const result=await api('/api/conversations/import-boss','POST',{});await loadWorkspace();notify(result.message||`沟通同步已返回：新增 ${result.imported??0} 段、更新 ${result.updated??0} 段，仅覆盖已采集范围。`);});
  else if(action==='refresh-conversation')run(button,async()=>{const result=await api(`/api/conversations/${encodeURIComponent(id)}/refresh`,'POST',{});state.selectedConversationId=id;await loadWorkspace();notify(result.message||'会话历史已读取，原文和摘要仅针对已采集范围。');});
  else if(action==='read-conversation-profile')run(button,async()=>{const result=await api(`/api/conversations/${encodeURIComponent(id)}/profile`,'POST',{});state.selectedConversationId=id;await loadWorkspace();resultNotice(result,'沟通人职业资料已读取，请核对来源范围。');});
  else if(action==='copy-reply-draft')run(button,async()=>{const conversation=byId('conversations',id);const draft=conversation?.replyPriority?.replyDraft&&!conversation.replyPriority.stale?conversation.replyPriority.replyDraft:'';if(!draft)throw new Error('当前会话尚无回复草稿。');try{await navigator.clipboard.writeText(draft);notify('回复草稿已复制，请审核后自行发送。');}catch{modal('手动复制回复草稿','复制和发送均由你确认；此处不会发送消息。',`<textarea id="reply-copy-text" class="control" style="width:100%;min-height:170px;line-height:2" readonly>${escape(draft)}</textarea>`,btn('close','关闭'),false,true);setTimeout(()=>{const field=document.getElementById('reply-copy-text');field?.focus();field?.select();},70);}});
  else if(action==='interview-automation-status')run(button,async()=>{await refreshInterviewAutomationStatus();notify('面试自动化运行状态已刷新。');});
  else if(action==='check-feishu-app')run(button,async()=>{const result=await api('/api/feishu/check','POST',{});await loadWorkspace();notify(result.message||'HR 应用检测完成。');});
  else if(action==='check-connections')run(button,async()=>{const result=await api('/api/connections/check','POST',{});await loadWorkspace();notify(result.message||'连接检测已完成，请查看各服务状态。');});
  else if(action==='generate-pack')run(button,async()=>{const result=await api('/api/interview-packs','POST',{applicationId:id});await loadWorkspace();const document=result.document||result.data?.document||result;notify(documentGenerationStatus(document).pending?'资料已收集，面试问题待生成。':'面试资料与问题已生成，请复核。');if(document.id)showDocument(document.id);else openCandidate(id,'materials');});
  else if(action==='mark-reviewed')run(button,async()=>{await api(`/api/applications/${encodeURIComponent(id)}`,'PATCH',{reviewStatus:'reviewed'});await loadWorkspace();notify('已记录人工复核。');openCandidate(id,'evidence');});
  else if(action==='sync-interview')run(button,async()=>{const result=await api(`/api/interviews/${encodeURIComponent(id)}/calendar`,'POST',{});await loadWorkspace();notify(result.message||'日历操作已返回，请核对日程状态。');showInterviewDetail(id);});
  else if(action==='interview-reminder-test')run(button,async()=>{const result=await api(`/api/interviews/${encodeURIComponent(id)}/reminder/send`,'POST',{action:'send_test_reminder'});await loadWorkspace();showInterviewDetail(id);const sent=Boolean(result.receipt?.messageId);notify(sent?'测试卡片已发送；正式提醒时间保持不变。':result.receipt?.error?.message||'测试卡片未确认发送，请核对回执。',!sent);});
  else if(action==='interview-status-refresh')run(button,()=>refreshExistingInterviewStatus(byId('interviews',id),{api,loadWorkspace,showInterviewDetail,notify}));
  else if(action==='initialize-feishu-confirm')run(button,async()=>{const result=await api('/api/feishu/initialize','POST',{});closeOverlay();await loadWorkspace();notify(result.message||'多维表初始化已完成，请查看连接状态。');});
  else if(action==='sync-feishu')run(button,async()=>{const result=await api('/api/feishu/sync','POST',{});await loadWorkspace();resultNotice(result,'飞书同步已返回，请查看执行记录。');});
  else if(action==='pull-feishu-confirm')run(button,async()=>{const result=await api('/api/feishu/pull','POST',{});closeOverlay();await loadWorkspace();notify(result.message||'已从飞书读取业务记录。');});
  else if(action==='automation-run')run(button,async()=>{const result=await api(`/api/automations/${encodeURIComponent(id)}/run`,'POST',{});await loadWorkspace();resultNotice(result,'工作流已返回，请查看执行记录。');});
});
document.addEventListener('input',event=>{if(candidateProfileEditor.handleInput(event)||recipientDirectory.handleInput(event)||sourcingCandidates.handleInput(event)||candidatePool.handleInput(event)||candidateInbox.handleInput(event))return;advanced.handleInput(event);const filter=event.target.dataset.filter;if(filter&&event.target.tagName==='INPUT'){state[filter]=event.target.value;render();}});
document.addEventListener('change',event=>{if(candidateProfileEditor.handleInput(event)||recipientDirectory.handleInput(event)||sourcingCandidates.handleInput(event)||candidatePool.handleInput(event)||candidateInbox.handleInput(event))return;advanced.handleInput(event);const filter=event.target.dataset.filter;if(filter){state[filter]=event.target.value;render();}});
document.addEventListener('keydown',event=>{if(recipientDirectory.handleKeydown(event))return;if(event.key==='Escape'){if(overlays.innerHTML)closeOverlay();else if(state.mobileOpen){state.mobileOpen=false;render();}}});
document.addEventListener('submit',event=>{
  if(candidateProfileEditor.handleSubmit(event))return;
  try{recipientDirectory.validateForm(event.target);}catch(error){event.preventDefault();notify(error.message,true);return;}
  if(candidatePool.handleSubmit(event))return;
  if(advanced.handleSubmit(event))return;
  const form=event.target;if(!['requirement-form','application-stage-form','application-notes-form','boss-import-form','schedule-picker-form','schedule-form','settings-form','interview-automation-settings-form','feishu-credentials-form','interview-notes-form','conversation-followup-form'].includes(form.id))return;
  event.preventDefault();if(!form.reportValidity())return;
  const values=Object.fromEntries(new FormData(form));const submitter=event.submitter || form.querySelector('button[type=submit]');
  if(form.id==='requirement-form')run(submitter,async()=>{values.headcount=Number(values.headcount);values.mustHaves=values.mustHaves.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);const id=form.dataset.id;await api(id?`/api/requirements/${encodeURIComponent(id)}`:'/api/requirements',id?'PATCH':'POST',values);closeOverlay();await loadWorkspace();notify(id?'需求与岗位标准已保存。':'招聘需求已创建。');});
  else if(form.id==='application-stage-form')run(submitter,async()=>{const id=form.dataset.id;await api(`/api/applications/${encodeURIComponent(id)}`,'PATCH',values);await loadWorkspace();notify('候选人阶段已保存。');openCandidate(id,state.drawerTab);});
  else if(form.id==='application-notes-form')run(submitter,async()=>{const id=form.dataset.id;await api(`/api/applications/${encodeURIComponent(id)}`,'PATCH',values);await loadWorkspace();notify('跟进记录已保存。');openCandidate(id,'notes');});
  else if(form.id==='boss-import-form')run(submitter,async()=>{if(isBossOffline(state.data))throw new Error('当前仅整理已保存资料，暂不连接 BOSS。');const result=await api('/api/candidates/import-boss','POST',{requirementId:values.requirementId,mode:'live'});closeOverlay();await loadWorkspace();notify(result.message||`本次新增 ${result.imported??0} 条，去重 ${result.deduplicated??0} 条。`);});
  else if(form.id==='schedule-picker-form')showScheduleForm(values.applicationId);
  else if(form.id==='schedule-form')run(submitter,async()=>{const payload=interviewSchedulePayload(values,form.dataset.id);let result;try{result=await api('/api/interviews','POST',payload);}catch(error){if(!error.payload?.interview)throw error;closeOverlay();await loadWorkspace();setView('interviews');advanced.showInterviewWorkspace(error.payload.interview.id,'prep');notify(error.message,true);return;}closeOverlay();await loadWorkspace();setView('interviews');const interview=result.interview||result.data?.interview||result;if(interview.id)advanced.showInterviewWorkspace(interview.id,'prep');notify(result.message||(payload.createCalendar?'面试已安排，资料与问题已准备；请核对飞书日程及机器人任务状态。':'本地面试与准备问题已保存，请核对提醒和入会任务状态。'));});
  else if(form.id==='feishu-credentials-form')run(submitter,async()=>{const field=form.elements.appSecret,appSecret=field.value;field.value='';const result=await api('/api/feishu/credentials','POST',{appId:state.data.settings.feishuConnection.appId,appSecret});await loadWorkspace();notify(result.message||'应用凭据已保存并验证。');});
  else if(form.id==='interview-automation-settings-form')run(submitter,()=>saveInterviewAutomationSettings(values));
  else if(form.id==='settings-form')run(submitter,async()=>{values.cdpPort=Number(values.cdpPort);values.bossOfflineMode=values.bossOfflineMode==='true';await api('/api/settings','POST',values);await loadWorkspace();notify('连接配置已保存，服务状态以检测结果为准。');});
  else if(form.id==='interview-notes-form')run(submitter,async()=>{await api(`/api/interviews/${encodeURIComponent(form.dataset.id)}/notes`,'POST',{transcript:values.transcript});await loadWorkspace();notify('访谈原文已保存，核对清单需要人工确认。');showInterviewDetail(form.dataset.id);});
  else if(form.id==='conversation-followup-form')run(submitter,async()=>{values.followUpAt=values.followUpAt?new Date(`${values.followUpAt}:00+08:00`).toISOString():'';await api(`/api/conversations/${encodeURIComponent(form.dataset.id)}`,'PATCH',values);state.selectedConversationId=form.dataset.id;await loadWorkspace();notify('沟通进度与跟进记录已保存，没有向 BOSS 发送消息。');});
});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(view!==state.view){closeOverlay();state.view=viewNames[view]?view:'overview';render();}});
loadWorkspace().catch(error=>{app.innerHTML=`<div class="error-page"><span class="brand-mark" style="margin:0 auto 20px">序</span><h1>工作台暂时无法连接</h1><p>${escape(error.message)}</p><button id="retry-load" class="btn primary">重新连接</button></div>`;document.getElementById('retry-load').addEventListener('click',()=>location.reload());});
